39: #[async_trait::async_trait]
40: impl PackageSearchApi for CliNpmSearchApi {
41:   async fn search(&self, query: &str) -> Result<Arc<Vec<String>>, AnyError> {
42:     if let Some(names) = self.search_cache.get(query) {
43:       return Ok(names.clone());
44:     }
45:     let mut search_url = npm_registry_url().join("-/v1/search")?;
46:     search_url
47:       .query_pairs_mut()
48:       .append_pair("text", &format!("{} boost-exact:false", query));
49:     let file = self
50:       .file_fetcher
51:       .fetch(&search_url, PermissionsContainer::allow_all())
52:       .await?
53:       .into_text_decoded()?;
54:     let names = Arc::new(parse_npm_search_response(&file.source)?);
55:     self.search_cache.insert(query.to_string(), names.clone());
56:     Ok(names)
57:   }
58: 
59:   async fn versions(&self, name: &str) -> Result<Arc<Vec<Version>>, AnyError> {
60:     if let Some(versions) = self.versions_cache.get(name) {
61:       return Ok(versions.clone());
62:     }
63:     let info = self
64:       .resolver
65:       .package_info(name)
66:       .await
67:       .ok_or_else(|| anyhow!("NPM package info not found: {}", name))?;
68:     let mut versions = info.versions.keys().cloned().collect::<Vec<_>>();
69:     versions.sort();
70:     versions.reverse();
71:     let versions = Arc::new(versions);
72:     self
73:       .versions_cache
74:       .insert(name.to_string(), versions.clone());
75:     Ok(versions)
76:   }
