86: fn parse_npm_search_response(source: &str) -> Result<Vec<String>, AnyError> {
87:   #[derive(Debug, Deserialize)]
88:   struct Package {
89:     name: String,
90:   }
91:   #[derive(Debug, Deserialize)]
92:   struct Object {
93:     package: Package,
94:   }
95:   #[derive(Debug, Deserialize)]
96:   struct Response {
97:     objects: Vec<Object>,
98:   }
99:   let objects = serde_json::from_str::<Response>(source)?.objects;
100:   Ok(objects.into_iter().map(|o| o.package.name).collect())
101: }
